import{_ as t,o as n,c as o,a2 as a}from"./chunks/framework.D66Xq0Kv.js";const u=JSON.parse('{"title":"Retirement","description":"","frontmatter":{"title":"Retirement"},"headers":[],"relativePath":"docs/personal-finance/retirement.md","filePath":"docs/personal-finance/retirement.md","lastUpdated":1794508483000}'),r={name:"docs/personal-finance/retirement.md"};function s(i,e,l,c,p,h){return n(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="retirement" tabindex="-1">Retirement <a class="header-anchor" href="#retirement" aria-label="Permalink to &quot;Retirement&quot;">​</a></h1><p>A <strong>Retirement Planning</strong> workbook connects spending and investment projects to show what your resources may support. It derives starting figures from the records you have already imported. Projections depend on those records and the assumptions shown; they are not predictions.</p><h2 id="start-with-an-outlook" tabindex="-1">Start with an outlook <a class="header-anchor" href="#start-with-an-outlook" aria-label="Permalink to &quot;Start with an outlook&quot;">​</a></h2><ol><li>Create spending and investment projects, or use the example household.</li><li>Choose <strong>New Workbook → Retirement Planning</strong> and select the source projects.</li><li>Confirm your household&#39;s ages and retirement timing in the planner&#39;s background information. Review any assumptions the workbook has filled in.</li><li>Check the derived balances, return, income and spending. Follow their source links when something looks wrong.</li></ol><p>More overlapping statement history improves the basis for the outlook. The analysis uses the history range currently available in the workbook.</p><h2 id="review-missing-information" tabindex="-1">Review missing information <a class="header-anchor" href="#review-missing-information" aria-label="Permalink to &quot;Review missing information&quot;">​</a></h2><p>Open the retirement workbook&#39;s <strong>Data Checks</strong> to see missing or uncertain inputs. Confirm whose accounts they are, review account types and fix source records where needed. Unassigned accounts can be modeled provisionally as yours; inspect that assumption before relying on an account-level projection.</p><p>Ownership can be skipped during project import. It becomes important here because account access and retirement timing depend on the owner.</p><h2 id="explore-the-questions" tabindex="-1">Explore the questions <a class="header-anchor" href="#explore-the-questions" aria-label="Permalink to &quot;Explore the questions&quot;">​</a></h2><p>The workbook&#39;s recipes connect spending, investments and retirement questions: stopping work, sustainable spending and taking a break. Review each answer&#39;s starting figures, assumptions and graph. Changing a recipe&#39;s inputs explores that question; it does not automatically replace your saved plan.</p><p>The <strong>Retirement Plan</strong> page holds the current planning assumptions. Available scenario controls let you explore spending, income, timing and account withdrawal sequences. Save or update a named plan to keep a change you want to use again. Plan access and activation are shown in <a href="/docs/settings/license">Settings → License</a>, without changing your source records.</p><p>To try the workflow before using your own records, open <strong>Demo Retirement</strong>. Example projects stay separate from real household data.</p>',12)])])}const m=t(r,[["render",s]]);export{u as __pageData,m as default};
